#include <bits/stdc++.h>
using namespace std;
using i128 = __int128_t;
i128 abs128(i128 x) {
    return x < 0 ? -x : x;
}
i128 gcd128(i128 a, i128 b) {
    a = abs128(a);
    b = abs128(b);
    while (b != 0) {
        i128 r = a % b;
        a = b;
        b = r;
    }
    return a;
}
string toStr(i128 x) {
    if (x == 0)
        return "0";
    bool neg = x < 0;
    x = abs128(x);
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    if (neg)
        s.push_back('-');
    reverse(s.begin(), s.end());
    return s;
}
struct Frac {
    i128 p, q;
    Frac(i128 n, i128 d) {
        if (d < 0)
            n = -n, d = -d;
        i128 g = gcd128(n, d);
        p = n / g;
        q = d / g;
    }
    string str() const {
        i128 n = abs128(p);
        if (q == 1)
            return toStr(n);
        return toStr(n) + "/" + toStr(q);
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long xa, ya, xb, yb;
    while (cin >> xa >> ya >> xb >> yb) {
        i128 x1 = xa, y1 = ya, x2 = xb, y2 = yb;
        i128 dx = x2 - x1, dy = y2 - y1;
        if (dx == 0 || dy == 0) {
            cout << "Error\n";
            continue;
        }
        Frac k(dy, dx);
        Frac bias(x2 * y1 - x1 * y2, dx);
        cout << "y=";
        if (k.p < 0)
            cout << '-';
        if (abs128(k.p) != k.q)
            cout << k.str();
        cout << 'x';
        if (bias.p != 0) {
            cout << (bias.p > 0 ? '+' : '-');
            cout << bias.str();
        }
        cout << '\n';
    }
    return 0;
}

