        cin >> x;
    if (n == 1) {
        cout << 1 << '\n';
        return 0;
    }
    vector<int> good(n - 1);
    for (int i = 0; i + 1 < n; ++i)
        good[i] = a[i] <= a[i + 1];
    SegmentTree tree(good);
    int ans = tree.best() + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            vector<int> edges = {i - 1, i, j - 1, j};
            sort(edges.begin(), edges.end());
            edges.erase(unique(edges.begin(), edges.end()), edges.end());
            swap(a[i], a[j]);
            for (int edge : edges) {
                if (edge >= 0 && edge + 1 < n)
                    tree.update(edge, a[edge] <= a[edge + 1]);
            }
            ans = max(ans, tree.best() + 1);
            swap(a[i], a[j]);
            for (int edge : edges) {
                if (edge >= 0 && edge + 1 < n)
                    tree.update(edge, good[edge]);
            }
        }
    }
    cout << ans << '\n';
    return 0;
