    _for(i, n) cin >> P[i];
    double l = 0, r = 1;
    while (1) {
        p = -1, q = -1;
        double mid = (l + r) / 2;
        LL cnt = find(mid);
        if (cnt == k)
            break;
        if (cnt < k)
            r = mid;
        else
            l = mid;
    }
    cout << p << "/" << q << "\n";
}
