    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        string x, y;
        cin >> x >> y;
        int relation = cmp(x, y);
        if (relation > 0)
            cout << "AZNB\n";
        else if (relation < 0)
            cout << "YZNB\n";
        else
            cout << "EASY GAME!\n";
