1592.official_explanation:
干饭时间
简单贪心；

每次只能去买两种东西，必须在第一种东西做好之前回来；

则，每次选取得两个数字不能相等；

最终结果等于每次选择的两个数字的最大值再加和；

为了最后的时间加和最小，则需要让每两个时间中最小的那个时间值，尽可能的大；

做法：先排序，每次选择两个不同的数，消耗的时间为较大的那个数值；

#include <iostream>
#include <cstdio>

int a[1010], b[1010];

void Sort(int a[], int n)
{
for (int i = n - 1; i > 0; i--)
for (int j = 0; j < i; j++)
if (a[j] > a[j + 1])
{
int t = a[j];
a[j] = a[j + 1];
a[j + 1] = t;
}
}

int main()
{
int n;
scanf("%d", &n);
for (int i = 0; i < n; i++)
scanf("%d", &a[i]);
Sort(a , n);
int ans = 0;
for (int i = n - 1; i >= 0; i--)
{
if (b[i])
continue;
ans += a[i];
for (int j = i - 1; j >= 0; j--)
{
if (!b[j] && a[j] < a[i])
{
b[j] = 1;
break;
}
}
}
printf("%d\n", ans);
return 0;
}

