#include <algorithm>
#include <cstring>
#include <cstdio>

#include <iostream>using namespace std;

const int N  = 1e3 , M = 2e6 ;

int n,cnt_x;
char a[N][N] ;
char x[M],y[M];

bool check(int n,int s){    //进行回文判断
if(n <= 0) return 0;
int t = (s - n) / 2 ;
cnt_x = 0 ;
for(int i = 1 ; i <= n ; i++) x[cnt_x++] = a[1+t][i+t] ;
for(int i = 2 ; i <= n ; i++) x[cnt_x++] = a[i+t][n+t] ;
for(int i = n -1  ; i >= 1 ; i --) x[cnt_x++] = a[n+t][i+t] ;
for(int i = n - 1 ; i >= 1;  i--) x[cnt_x++] = a[i+t][1+t] ;
memcpy(y,x,cnt_x + 1) ;
reverse(y,y+cnt_x) ;
x[cnt_x] = y[cnt_x] = 0 ;

if(!strcmp(x,y)) return 1 ;
return 0 ;
}

int main(){

int t ;
scanf("%d",&t) ;

while(t--){
scanf("%d",&n) ;

for(int i = 1; i <= n ; i ++) scanf("%s",a[i] + 1) ;

int t = n ;
while(check(t,n)){
t  -= 2 ;
}

if(t > 0) puts("No") ;
else puts("Yes") ;
}
return 0;
}

