using namespace std;
long long gcdll(long long a, long long b) {
    while (b) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> value(n + 1);
    for (int i = 1; i <= n; ++i)
        cin >> value[i];
    map<long long, long long> dp;
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        map<long long, long long> next;
        auto relax = [&](long long divisor, long long cost) {
            auto pos = next.find(divisor);
            if (pos == next.end() || cost < pos->second) {
                next[divisor] = cost;
            }
        };
        for (const auto& state : dp) {
            long long g = state.first;
            long long currentCost = state.second;
            relax(gcdll(g, value[i]), currentCost);
            long long changed = gcdll(value[i], static_cast<long long>(i));
            relax(gcdll(g, changed), currentCost + (n - i + 1));
        }
        dp.swap(next);
    }
    cout << dp[1] << '\n';
    return 0;
}

