scanf("%d", &m);
for (int i = 1, j = 2; i <= m / 2;)
{
if (sum == m)
{
ans ++ ;
sum -= i;
i ++ ;
}
else if (sum < m)
{
j ++ ;
sum += j;
}
else
{
sum -= i;
i ++ ;
}
}
