for (int i = 2; i <= n; i ++ )
{
g = gcd(g, a[i]);
}
int ans = 0;
if (g != 1)
{
if (gcd(g, n) == 1)	ans = 1;
else if (gcd(g, n - 1) == 1)	ans = 2;
else	ans = 3;
}
printf("%d", ans);
return 0;
}

