int now = 0;
for (int i = 0; i < n; i++) {
if (str[i] == 'g') {
now += a[0][now % 3];
} else if (str[i] == 'y') {
now += a[1][now % 3];
} else if (str[i] == 'r') {
now += a[2][now % 3];
}
ti[i] = now;
}
for (int i = 1; i <= q; i++) {
int x;
scanf("%d", &x);
printf("%02d:%02d\n", ((ti[x - 1] + m) / 60 + h) % 24, (ti[x - 1] + m) % 60);
}
return 0;
}
