1793.official_explanation:
一半一半

题意：

求出所给直线把整个平面分割成的块数

解法：

#include <stdio.h>
#include <math.h>
#define eps 1e-5
struct line {
int a, b;
} lines[505];
typedef struct point {
double x, y;
} point;
//用来标记这条直线是否和前面的直线重合
int st[505];
int main() {
long long ans = 0;
int n;
//读入
scanf("%d", &n);
for (int i = 0; i < n; i++) {
//读入直线
scanf("%d%d", &lines[i].a, &lines[i].b);
//创建一个数组用来存放这条直线与前面几条直线的交点
point points[505] = {0};
int cnt = 0;
for (int j = 0; j < i; j++) {
//如果这条直线与其他直线重复（重合）就跳过
if (st[j]) continue;
// 与第j条线平行
if (lines[i].a == lines[j].a) {
// 与第j条线重合
if (lines[i].b == lines[j].b) {
// 标记为重复，没有增加任何分块，直接break
st[i] = 1;
break;
} else {
// 仅平行，没有焦点
continue;
}
}
point p;
// 计算出直线i和直线j的交点坐标
p.x = (lines[j].b - lines[i].b) * 1.0 / (lines[i].a - lines[j].a);
p.y = (lines[i].a * p.x + lines[i].b);
int flag = 1;
for (int k = 0; k < cnt; k++) {
//如果与之前计算的交点重复则不计入（这里有误差判断）
if (fabs(points[k].x - p.x) < eps && fabs(points[k].y - p.y) < eps) {
flag = 0;
break;
}
}
if (flag) {
points[cnt++] = p;
}
}
// 与前面的所有直线有cnt个交点，即增加了cnt+1个分块
if (!st[i]) ans += cnt + 1;
}
// 输出ans+1(因为初始时相当于一整块区域)
printf("%lld", ans + 1);
return 0;
}
