#include<stdio.h>
int fun(int x,int a[],int *ans)//转换成二进制，储存1的个数并返回最高位数
{
int n = 0;
while(x)
{//x&1就是判断二进制最低位是否为1即是否是偶数
if(x&1)a[++n] = 1,(*ans)++;
else a[++n] = 0;
x>>= 1;// 右移一位， 就是x/=2;
}
return n;
}
int min(int x,int y)//返回最小值
{
if(x>y) return y;
else return x;
}
int main()
{
int t;
