#include <bits/stdc++.h>
using namespace std;
struct Player {
    long long hp, maxHp, mp, attack, heal, shieldValue, skillCost;
    long long shield = 0;
    int shieldTurns = 0;
    string name;
};
void beginTurn(Player& player) {
    if (player.shieldTurns > 0)
        --player.shieldTurns;
    if (player.shieldTurns == 0)
        player.shield = 0;
}
void hit(const Player& attacker, Player& defender) {
    long long damage = attacker.attack;
    long long absorbed = min(defender.shield, damage);
    defender.shield -= absorbed;
    defender.hp -= damage - absorbed;
}
void act(Player& actor, Player& opponent, int op) {
    if (op == 1) {
        hit(actor, opponent);
    } else if (op == 2) {
        actor.hp = min(actor.maxHp, actor.hp + actor.heal);
    } else if (op == 3) {
        actor.shield = actor.shieldValue;
        actor.shieldTurns = 3;
    } else if (op == 4 && actor.mp >= actor.skillCost) {
        actor.mp -= actor.skillCost;
        for (int repeat = 0; repeat < 3; ++repeat)
            hit(actor, opponent);
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        Player jxh, lhy;
        cin >> jxh.hp >> jxh.mp >> jxh.attack >> jxh.heal >> jxh.shieldValue >>
            jxh.skillCost;
        cin >> lhy.hp >> lhy.mp >> lhy.attack >> lhy.heal >> lhy.shieldValue >>
            lhy.skillCost;
        jxh.maxHp = jxh.hp;
        lhy.maxHp = lhy.hp;
        jxh.name = "jxh";
        lhy.name = "lhy";
        Player* first = &jxh;
        Player* second = &lhy;
        if (jxh.attack < lhy.attack)
            swap(first, second);
        int rounds;
        cin >> rounds;
        string winner;
        for (int round = 0; round < rounds; ++round) {
            int op1, op2;
            cin >> op1 >> op2;
            if (!winner.empty())
                continue;
            beginTurn(*first);
            act(*first, *second, op1);
            if (second->hp <= 0) {
                winner = first->name;
                continue;
            }
            beginTurn(*second);
            act(*second, *first, op2);
            if (first->hp <= 0)
                winner = second->name;
        }
        if (winner.empty())
            cout << "-_-\n";
        else if (winner == "jxh")
            cout << "不愧是你啊，jxh！\n";
        else
            cout << "lhy！lhy！lhy！！！\n";
    }
    return 0;
}

