        if (e & 1)
            res = (u128)res * a % mod;
        a = (u128)a * a % mod;
        e >>= 1;
    }
    return res;
}
bool isPrime(u64 n) {
    if (n < 2)
        return false;
    for (u64 p :
         {2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL, 17ULL, 19ULL, 23ULL, 29ULL, 31ULL, 37ULL}) {
        if (n % p == 0)
            return n == p;
    }
    u64 d = n - 1, s = 0;
    while ((d & 1) == 0)
        d >>= 1, ++s;
    for (u64 a : {2ULL, 325ULL, 9375ULL, 28178ULL, 450775ULL, 9780504ULL, 1795265022ULL}) {
        if (a % n == 0)
            continue;
        u64 x = powerMod(a % n, d, n);
        if (x == 1 || x == n - 1)
            continue;
        bool composite = true;
        for (u64 r = 1; r < s; ++r) {
            x = (u128)x * x % n;
            if (x == n - 1) {
                composite = false;
                break;
            }
        }
        if (composite)
            return false;
    }
    return true;
}
int main() {
    u64 a, b;
    cin >> a >> b;
    bool ans = (a == 1 && isPrime(b)) || (b == 1 && isPrime(a));
    cout << (ans ? "YES" : "NO") << '\n';
    return 0;
}

