int sum = 0 ;
for(int i = 1 ; i <= n ; ++ i){
if(sum + num[i] > mid) {
segements ++ ;
sum = 0 ;
}
sum += num[i] ;
}
if(segements > k) flag = 1 ; //说明这种分法不可行 需要的段数超过了要求
else flag = 0 ;
if(flag) lt = mid + 1 ;
else rt = mid ;
}
