int s1 = 1, s2 = 1;//s1和s2可以是a数组和b数组的指针，也可以是横纵分成的块数
for (int i = 1; i <= n-1; i++)
{
cin >> a[i];
}
for (int i = 1; i <= m - 1; i++)
{
cin >> b[i];
}
for(int i=1;i<=n-1;i++)
{
for(int j=1;j<=n-1-i;j++)
{
if(a[j]<a[j+1])
{
int t;
t=a[j];
a[j]=a[j+1];
a[j+1]=t;
}
}
}
for(int i=1;i<=m-1;i++)
{
for(int j=1;j<=m-1-i;j++)
{
if(b[j]<b[j+1])
{
int t;
t=b[j];
b[j]=b[j+1];
b[j+1]=t;
}
}
}
long long ans = 0;
for (int i = 2; i < n + m; i++)
{
if (a[s1] > b[s2])
ans += s2 * a[s1++];//选择大的，这里s2表示块数，s1指针后移一位
else
ans += s1 * b[s2++];//同理，和上面相反
}
