    int cnt1 = 0, cnt2 = 0; // cnt1,cnt2分别表示序列p，q的元素数量
    int ans = 0;
    for (auto t : mp) {
        int w = t.first, v = t.second;
        if (v % 2 == 0 && (v / 2) % 2 == 0)
            v1.push_back(w);
        if (v % 2 == 0 && (v / 2) % 2 == 1)
            v2.push_back(w);
        if (v % 2 == 1)
            v3.push_back(w);
    }
    ans += v2.size() * 2;
    if (v3.size() != 0) {
        for (int i = 0; i < v1.size(); i++) {
            int t = mp[v1[i]];
            if (cnt1 > cnt2)
                cnt1 += (t / 2) - 1, cnt2 += (t / 2) + 1;
            else
                cnt1 += (t / 2) + 1, cnt2 += (t / 2) - 1;
            ans += 2;
        }
        ans += v3.size();
    } else {
        if (v1.size() % 2 == 1)
            ans += (v1.size() - 1) * 2;
        else
            ans += v1.size() * 2;
    }
    cout << ans << endl;
}
int main() {
    int t;
    // cin>>t;
    t = 1;
    while (t--) {
        solve();
    }
    return 0;
}

