#include <bits/stdc++.h>
using namespace std;
struct Candidate {
    int diff, left, right;
    bool operator>(const Candidate& other) const {
        return tie(diff, left, right) > tie(other.diff, other.left, other.right);
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string gender;
    cin >> gender;
    gender = " " + gender;
    vector<int> skill(n + 1), left(n + 1), right(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> skill[i];
        left[i] = i - 1;
        right[i] = i + 1;
    }
    priority_queue<Candidate, vector<Candidate>, greater<Candidate>> heap;
    auto addCandidate = [&](int a, int b) {
        if (a >= 1 && b <= n && gender[a] != gender[b]) {
            heap.push({abs(skill[a] - skill[b]), a, b});
        }
    };
    for (int i = 1; i < n; ++i)
        addCandidate(i, i + 1);
    vector<pair<int, int>> ans;
    while (!heap.empty()) {
        Candidate cur = heap.top();
        heap.pop();
        int x = cur.left, y = cur.right;
        if (right[x] != y || left[y] != x)
            continue;
        ans.push_back({x, y});
        int nl = left[x], nr = right[y];
        if (nl >= 1)
            right[nl] = nr;
        if (nr <= n)
            left[nr] = nl;
        right[x] = left[y] = -1;
        addCandidate(nl, nr);
    }
    cout << ans.size() << '\n';
    for (auto [l, r] : ans) {
        cout << l << ' ' << r << '\n';
    }
    return 0;
}

